from pysat.solvers import Solver
from itertools import combinations

n = 15
# map each pair (u,v) with u<v to a variable index (1-based for pysat)
var = {}
cnt = 0
for u in range(n):
    for v in range(u+1, n):
        cnt += 1
        var[(u,v)] = cnt

print("Number of edge variables:", cnt)

solver = Solver(name='g3')

# Triangle-free constraints: for each triple, at most two edges => not all three
for u,v,w in combinations(range(n), 3):
    # clause: ~x_uv OR ~x_vw OR ~x_uw
    solver.add_clause([-var[(u,v)], -var[(v,w)], -var[(u,w)]])

# Maximal constraints: for each pair (i,j), if not edge, then exists k such that edges (i,k) and (j,k)
# We'll use auxiliary variables y_{i,j,k} for each pair (i,j) and k != i,j
# Let's define y_var index starting after edge variables
y_var = {}
base = cnt
for i,j in combinations(range(n), 2):
    for k in range(n):
        if k == i or k == j:
            continue
        base += 1
        y_var[(i,j,k)] = base

print("Number of y variables:", base - cnt)

# Add constraints for y and maximal
for i,j in combinations(range(n), 2):
    # clause: x_{i,j} OR OR_{k} y_{i,j,k}
    clause = [var[(i,j)]]
    for k in range(n):
        if k == i or k == j:
            continue
        clause.append(y_var[(i,j,k)])
    solver.add_clause(clause)

    for k in range(n):
        if k == i or k == j:
            continue
        y = y_var[(i,j,k)]
        # y -> x_{i,k}
        solver.add_clause([-y, var[tuple(sorted((i,k)))]]])
        # y -> x_{j,k}
        solver.add_clause([-y, var[tuple(sorted((j,k)))]]])
        # x_{i,k} AND x_{j,k} -> y
        solver.add_clause([-var[tuple(sorted((i,k)))], -var[tuple(sorted((j,k)))], y])

# Fixed edges
fixed = [(2,14), (6,13), (7,13), (10,13), (6,14)]
for u,v in fixed:
    if u > v:
        u,v = v,u
    solver.add_clause([var[(u,v)]])

print("Total variables:", base)
print("Solving...")
sat = solver.solve()
print("SAT:", sat)
if sat:
    model = solver.get_model()
    # extract edges
    edges = []
    for (u,v), idx in var.items():
        if idx in model:
            edges.append((u,v))
    print("Number of edges:", len(edges))
    print("Edges:", edges)
else:
    print("UNSAT")

